function importChart(points,group,unit){const data=points.filter(x=>x.group===group).slice(-180);if(!data.length)return '<p class="empty-receipts">No observations for this category.</p>';const vals=data.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,W=760,H=240,L=58,R=14,T=18,B=30,dated=data.every(p=>/^\d{4}-\d{2}-\d{2}$/.test(p.date)),times=dated?data.map(p=>Date.parse(p.date)):[],t0=times[0],t1=times.at(-1),x=i=>dated&&t1>t0?L+(times[i]-t0)*(W-L-R)/(t1-t0):L+i*(W-L-R)/Math.max(1,data.length-1),y=v=>T+(max-v)*(H-T-B)/span,path=data.map((p,i)=>`${i?'L':'M'}${x(i)},${y(p.value)}`).join(' ');return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Imported series for ${esc(group)} measured in ${esc(unit||'unspecified units')}"><line class="gridline" x1="${L}" x2="${W-R}" y1="${T}" y2="${T}"/><line class="gridline" x1="${L}" x2="${W-R}" y1="${H-B}" y2="${H-B}"/><text x="${L-8}" y="${T+3}" text-anchor="end">${max}</text><text x="${L-8}" y="${H-B+3}" text-anchor="end">${min}</text><path class="series" stroke="#275bd7" d="${path}"/>${data.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.value)}" r="3" fill="#275bd7"><title>${esc(p.date)}: ${p.value} ${esc(unit||'')}</title></circle>`).join('')}<text x="${L}" y="${H-7}">${esc(data[0].date)}</text><text x="${W-R}" y="${H-7}" text-anchor="end">${esc(data[data.length-1].date)}</text></svg>`}
