function cleanedSeriesCsv(data,group){const columns=['date','group','value','source_name','source_url','unit','geography'];return [columns.map(csvCell).join(','),...data.rows.filter(p=>p.group===group).map(p=>[p.date,p.group,p.value,data.sourceName||data.name,data.url,data.unit,data.geography].map(csvCell).join(','))].join('\r\n')}
